To create a Flutter app for habit tracking, you can follow these steps:

1. Start by creating a new Flutter project using the command `flutter create habit_tracker`.
2. Add the necessary dependencies by running `flutter add fluttertoast` to use the Toast package for notifications.
3. In the `habit_tracker` directory, create a new file named `habit_tracker.dart` to define the habit tracking functionality.
4. In the `habit_tracker.dart` file, add the following code to track daily habits:

```dart
import 'package:flutter/material.dart';
import 'package:habit_tracker/habit.dart';
import 'package:habit_tracker/habit_tracker.dart';

class HabitTracker extends StatefulWidget {
  @override
  _HabitTrackerState createState() => _HabitTrackerState();
}

class _HabitTrackerState extends State<HabitTracker> {
  List<Habit> habits = [];
  int totalPoints = 0;
  int aggregateScore = 0;

  void _addHabit(Habit habit) {
    habits.add(habit);
    totalPoints += habit.points;
    aggregateScore += habit.points;
    setState(() {});
  }

  void _calculateAggregateScore() {
    aggregateScore = totalPoints;
    setState(() {});
  }

  void _calculateTotalPoints() {
    totalPoints = 0;
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Habit Tracker'),
      ),
      body: ListView.builder(
        itemCount: habits.length,
        itemBuilder: (context, index) {
          return ListTile(
            title: Text(habits[index].name),
            subtitle: Text(habits[index].description),
            trailing: Text('Points: ${habits[index].points}'),
          );
        },
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: _addHabit,
        child: Icon(Icons.add),
      ),
      floatingActionButtonLocation: FloatingActionButtonLocation.centerFloat,
    );
  }
}
```

